excels.excel:

EXPORT WITH SHEET="费用报销明细表", HEADER=true,
    MAPPING={"a":"部门","b":"报销人","c":"费用类型","d":"申请日期","e":"金额"},
    FORMAT={"d":"yyyy-MM-dd","e":"#,##0.00"},
    FORMULAS={
        E5:'SUM(E2:E4)',
        E8:'SUM(E6:E7)',
        E12:'SUM(E9:E11)',
        E13:'E5+E8+E12'
    },
    STYLE={
        ROW 5:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        ROW 12:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        ROW 13:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}
    },
    MERGE:{
        RANGE A2:A4 WITH MERGE_WITH_FIRST,
        RANGE A6:A7 WITH MERGE_WITH_FIRST,
        RANGE A9:A11 WITH MERGE_WITH_FIRST
    }
